export function frameStyle([x, y, width, height]) {
  return { left: `${x / CANVAS_SIZE.width * 100}%`, top: `${y / CANVAS_SIZE.height * 100}%`, width: `${width / CANVAS_SIZE.width * 100}%`, height: `${height / CANVAS_SIZE.height * 100}%` };
}
